{
  "avaliacoes": [
    {
      "id": "Ed6e2bd82024825f8",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No processamento primário de petróleo, a produção simultânea de gás, óleo, água, sólidos e outras impurezas exige facilidades de produção para separação e tratamento dos fluidos, conectando diretamente o desempenho dessas facilidades ao resultado produtivo da unidade.",
          "trechos": [
            "Ed6e2bd82024825f8:0:700"
          ],
          "condicoes": [
            "aplica-se ao processamento primário ao longo da vida produtiva de um campo de petróleo",
            "o interesse econômico mencionado recai sobre hidrocarbonetos, com tratamento associado de água para descarte"
          ],
          "limites": [
            "o trecho é introdutório e não apresenta KPI, fórmula de balanço ou método de cálculo de perdas",
            "não distingue FPSO de outros tipos de unidade já no trecho principal"
          ]
        },
        {
          "proposicao": "Equipamentos inoperantes ou operando abaixo da eficiência esperada podem afetar a qualidade dos fluidos separados e estão associados, no texto, a perdas de produção e/ou queda na qualidade dos fluidos produzidos.",
          "trechos": [
            "Ed6e2bd82024825f8:700:1393"
          ],
          "condicoes": [
            "observação referida a algumas plantas",
            "os problemas são associados a equipamentos da planta de separação"
          ],
          "limites": [
            "o trecho não quantifica a perda de produção nem a degradação de qualidade",
            "a relação causal é apresentada de forma geral, sem discriminar cada equipamento ou mecanismo"
          ]
        },
        {
          "proposicao": "O texto atribui problemas operacionais de plantas de separação a envelhecimento de equipamentos, manutenção inadequada, problemas de projeto e modificações nas plantas, oferecendo um conjunto de causas técnicas candidatas para atribuição de perdas e restrições operacionais.",
          "trechos": [
            "Ed6e2bd82024825f8:700:1393"
          ],
          "condicoes": [
            "referido a três plantas de separação em três tipos distintos de unidades estacionárias de produção na Bacia de Campos"
          ],
          "limites": [
            "os trechos fornecidos não detalham a evidência empírica de cada causa",
            "não se pode generalizar que todas as perdas em FPSO decorram dessas causas"
          ]
        }
      ]
    },
    {
      "id": "Ea50155fb6ec51958",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Obstrução na coluna por incrustação é associada à queda de pressão observada no PDG em certos intervalos e à queda da vazão bruta do poço, caracterizando mecanismo de perda de produção por restrição de escoamento.",
          "trechos": [
            "Ea50155fb6ec51958:0:694"
          ],
          "condicoes": [
            "baseado no exemplo de comportamento de poço submetido a operações de squeeze e remoção de incrustação"
          ],
          "limites": [
            "o trecho descreve um exemplo e não um critério universal para diagnóstico",
            "não informa magnitudes numéricas de perda nem frequência de ocorrência"
          ]
        },
        {
          "proposicao": "Operações de inibição podem proporcionar recuperação parcial da produção, enquanto a recuperação total da vazão do poço é associada, no exemplo, à operação de remoção, apresentada como mais demorada e onerosa.",
          "trechos": [
            "Ea50155fb6ec51958:694:1384"
          ],
          "condicoes": [
            "aplica-se ao caso em que há incrustação formada e ao exemplo descrito no texto"
          ],
          "limites": [
            "não há metodologia comparativa completa entre alternativas",
            "o trecho não permite inferir tempos, custos ou eficácia para todos os poços"
          ]
        },
        {
          "proposicao": "A prevenção de incrustações é apresentada como parte da estratégia de desenvolvimento de campo offshore, devendo considerar riscos de ocorrência e desafios de gerenciamento, com o objetivo de reduzir custos advindos de perdas de produção.",
          "trechos": [
            "Ea50155fb6ec51958:694:1384",
            "Ea50155fb6ec51958:1384:2079"
          ],
          "condicoes": [
            "voltado a desenvolvimento de campo offshore de petróleo",
            "as técnicas mencionadas são as principais encontradas na literatura e adotadas na indústria offshore segundo o texto"
          ],
          "limites": [
            "o trecho lista técnicas, mas não oferece critérios de seleção, compatibilidade entre elas ou dosagens operacionais completas",
            "não quantifica a redução de perdas obtida por cada técnica"
          ]
        }
      ]
    },
    {
      "id": "E3a62b13e285f3be8",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Indicadores de desempenho são definidos como medidas quantitativas ou qualitativas monitoradas e avaliadas periodicamente, podendo indicar o desempenho da organização; a norma distingue indicadores reativos e pró-ativos.",
          "trechos": [
            "E3a62b13e285f3be8:0:693"
          ],
          "condicoes": [
            "aplica-se ao regime de segurança operacional de sistemas submarinos e ao SGSS"
          ],
          "limites": [
            "o trecho conceitua indicadores no contexto de segurança operacional, não um KPI de produção específico de FPSO",
            "não estabelece fórmula de balanço produtivo, disponibilidade ou perda de produção"
          ]
        },
        {
          "proposicao": "Indicadores reativos representam o tempo de reação a eventos não desejados, como taxas de incidentes ou outras medidas de desempenho passado, enquanto indicadores pró-ativos avaliam condições que possam iniciar ou contribuir para incidentes operacionais.",
          "trechos": [
            "E3a62b13e285f3be8:0:693"
          ],
          "condicoes": [
            "uso orientado à avaliação do desempenho organizacional frente a incidentes operacionais"
          ],
          "limites": [
            "a norma não afirma que esses indicadores, por si, medem perdas produtivas",
            "a aplicação direta a gargalos de processo em FPSO é indireta"
          ]
        },
        {
          "proposicao": "Mecanismo de falha e modo de falha são definidos como fenômenos ou formas de manifestação que causam perda de resistência, funcionalidade ou reserva de operacionalidade, fornecendo base normativa para rastrear indisponibilidades e suas causas técnicas.",
          "trechos": [
            "E3a62b13e285f3be8:693:1388"
          ],
          "condicoes": [
            "aplica-se a materiais, partes, estruturas, meios, superfícies, interações, operações ou controles no sistema submarino"
          ],
          "limites": [
            "o trecho não converte falhas em impacto quantitativo de produção",
            "o escopo normativo principal é sistema submarino, não toda a unidade FPSO"
          ]
        }
      ]
    },
    {
      "id": "Ed85bfe4e07ff8b16",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": [
        {
          "proposicao": "Os trechos reúnem referências, diretrizes internas, glossário e um exemplo de alerta de perda de produção por alto teor de areia em poço, mas não oferecem explicação técnica suficiente para balanços, produção potencial ou critérios de atribuição de causas no recorte solicitado.",
          "trechos": [
            "Ed85bfe4e07ff8b16:0:696",
            "Ed85bfe4e07ff8b16:696:1387",
            "Ed85bfe4e07ff8b16:1387:2086",
            "Ed85bfe4e07ff8b16:2086:2481"
          ],
          "condicoes": [],
          "limites": [
            "predomina caráter bibliográfico e glossarial",
            "o caso de perda por areia aparece sem método, contexto operacional completo ou detalhamento causal"
          ]
        }
      ]
    },
    {
      "id": "E4de1fa8dbda2169d",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "O estudo de caso de debottlenecking em unidade de destilação a vácuo identifica como limitações principais a temperatura de saída do forno e a capacidade máxima de remoção de calor nos circuitos de refluxo circulante, exemplificando como gargalos podem ser localizados em variáveis de processo e em equipamentos específicos.",
          "trechos": [
            "E4de1fa8dbda2169d:0:693",
            "E4de1fa8dbda2169d:693:1393"
          ],
          "condicoes": [
            "aplica-se ao caso de uma unidade de destilação a vácuo",
            "as conclusões decorrem de estudo de caso combinando modelos de simulação e dados testados em planta real"
          ],
          "limites": [
            "o contexto é refino, não FPSO/FSO",
            "não deve ser convertido em regra universal para unidades offshore"
          ]
        },
        {
          "proposicao": "No caso relatado, diversas modificações de processo foram associadas aos efeitos mais significativos no alívio de gargalos, incluindo novo circuito de refluxo, redução da pressão de operação da torre, otimização da taxa de vapor de stripping e substituição de pratos da seção de esgotamento.",
          "trechos": [
            "E4de1fa8dbda2169d:693:1393"
          ],
          "condicoes": [
            "referido às modificações implementadas na unidade de destilação a vácuo estudada"
          ],
          "limites": [
            "o trecho não quantifica ganho de capacidade, impacto em perdas ou custo das mudanças",
            "não há critérios transferíveis diretamente para seleção em FPSOs"
          ]
        },
        {
          "proposicao": "Conhecer a modelagem do processo, o desenho dos equipamentos e o desempenho dos equipamentos é apresentado como crucial para elevar rendimentos e qualidades de produtos com o mínimo possível de paradas não programadas.",
          "trechos": [
            "E4de1fa8dbda2169d:1393:2089"
          ],
          "condicoes": [
            "aplica-se às ações de revamp e reengenharia de unidades de vácuo no caso e autores citados"
          ],
          "limites": [
            "o texto trata de produtos de refino, não de balanço de produção em FPSO",
            "não define indicadores formais nem método de controle operacional"
          ]
        }
      ]
    },
    {
      "id": "E3414dcbc70adf8cf",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Infraestruturas insuficientes de transporte, armazenagem e exportação são descritas como gargalo para a indústria petrolífera, mostrando que restrições fora do poço e fora da planta de processo também podem limitar o aproveitamento da produção.",
          "trechos": [
            "E3414dcbc70adf8cf:0:699"
          ],
          "condicoes": [
            "aplica-se ao cenário nacional descrito no texto"
          ],
          "limites": [
            "o caso é do Iraque, não do Brasil nem de uma instalação FPSO específica",
            "números essenciais estão apagados"
          ]
        },
        {
          "proposicao": "A insuficiência de capacidade de processamento de gás é associada, no texto, à queima de parte da produção, caracterizando perda de aproveitamento decorrente de limitação de infraestrutura.",
          "trechos": [
            "E3414dcbc70adf8cf:699:1398"
          ],
          "condicoes": [
            "referido ao contexto descrito de crescimento da produção sem expansão compatível das instalações"
          ],
          "limites": [
            "os valores numéricos foram apagados",
            "o exemplo é setorial e geográfico, não um balanço operacional de FPSO"
          ]
        },
        {
          "proposicao": "O texto afirma que insuficiência de instalações de armazenamento pode levar à parada na produção quando há interrupção ou atraso no carregamento de petroleiros em instalações offshore, estabelecendo relação entre logística de exportação e perda produtiva.",
          "trechos": [
            "E3414dcbc70adf8cf:1398:2097"
          ],
          "condicoes": [
            "aplica-se ao caso em que o escoamento por carregamento marítimo sofre interrupção ou atraso"
          ],
          "limites": [
            "o trecho é um exemplo de país e infraestrutura específicos",
            "não separa perdas planejadas e não planejadas nem oferece método de mensuração"
          ]
        }
      ]
    }
  ],
